fn test_q3_object(object: u32, object_type: u32) -> PpcQ3ObjectRecord {
    PpcQ3ObjectRecord {
        object,
        kind: PpcQ3ObjectKind::Generic,
        object_type,
        source: PpcQ3ObjectSource::default(),
        data_ptr: 0,
        data_size: 0,
    }
}

fn run_test_import(loaded: &mut PpcLoadedApp, target: PpcImportDispatcherTarget) {
    loaded.cpu.pc = loaded.entry_pc;
    loaded.cpu.lr = PPC_HALT_PC;
    loaded.imports[0].dispatcher_target = target;
    let probe = loaded.run_with_hle_imports(64);
    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    drain_test_m68k_guest_calls(loaded);
}

fn create_test_cwindow(
    loaded: &mut PpcLoadedApp,
    bounds_ptr: u32,
    bounds: (i16, i16, i16, i16),
    proc_id: i16,
    visible: bool,
    behind: u32,
) -> u32 {
    ppc_write_rect(&mut loaded.memory, bounds_ptr, bounds.0, bounds.1, bounds.2, bounds.3)
        .unwrap();
    loaded.cpu.gpr[3] = 0;
    loaded.cpu.gpr[4] = bounds_ptr;
    loaded.cpu.gpr[5] = 0;
    loaded.cpu.gpr[6] = u32::from(visible);
    loaded.cpu.gpr[7] = proc_id as u16 as u32;
    loaded.cpu.gpr[8] = behind;
    loaded.cpu.gpr[9] = 1;
    loaded.cpu.gpr[10] = 0;
    run_test_import(loaded, PpcImportDispatcherTarget::NewCWindow);
    let window = loaded.cpu.gpr[3];
    assert_ne!(window, 0, "test NewCWindow must succeed");
    window
}

fn initialize_test_cgraf_port(bus: &mut MacMemoryBus, port: u32) {
    bus.write_word(port + 6, 0xc000);
    for offset in [36, 38, 40] {
        bus.write_word(port + offset, 0);
    }
    for offset in [42, 44, 46] {
        bus.write_word(port + offset, u16::MAX);
    }
    bus.write_word(port + PPC_CGRAF_PORT_PN_SIZE_OFFSET, 1);
    bus.write_word(port + PPC_CGRAF_PORT_PN_SIZE_OFFSET + 2, 1);
    bus.write_word(port + PPC_CGRAF_PORT_PN_MODE_OFFSET, PPC_QD_PEN_MODE_PAT_COPY as u16);
    bus.write_word(
        port + PPC_CGRAF_PORT_TX_MODE_OFFSET,
        PPC_QD_TEXT_MODE_SRC_OR as u16,
    );
    bus.write_word(
        port + PPC_CGRAF_PORT_TX_SIZE_OFFSET,
        PPC_QD_TEXT_SIZE_SYSTEM as u16,
    );
}

fn run_test_import_with_process_memory_manager(
    loaded: &mut PpcLoadedApp,
    target: PpcImportDispatcherTarget,
    memory_manager: &SharedProcessMemoryManager,
) {
    loaded.cpu.pc = loaded.entry_pc;
    loaded.cpu.lr = PPC_HALT_PC;
    loaded.imports[0].dispatcher_target = target;
    let probe = loaded.run_with_process_memory_manager(
        64,
        false,
        false,
        &mut memory_manager.borrow_mut(),
    );
    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    drain_test_m68k_guest_calls(loaded);
}

fn attach_test_classic_heap(
    native: &mut PpcLoadedApp,
    context: &mut ProcessContext,
    ram_size: usize,
    heap_len: usize,
) -> MacMemoryBus {
    let mut classic_bus = MacMemoryBus::new(ram_size);
    context.attach_classic_memory_bus(&mut classic_bus);
    let classic_heap = classic_bus
        .shared_ram_region(0x0020_0000, heap_len as u32)
        .expect("classic adapter owns its heap range");
    context.attach_memory(0x0020_0000, classic_heap, &mut native.memory);
    classic_bus
}

fn drain_test_m68k_guest_calls(loaded: &mut PpcLoadedApp) {
    while let Some(pending) = loaded.guest_calls()
        .active_m68k()
        .or_else(|| loaded.guest_calls().activate_m68k())
    {
        let mut cpu = m68k::CpuCore::new();
        cpu.set_cpu_type(REFERENCE_MACHINE_PROFILE.cpu_type());
        cpu.pc = pending.entry;
        cpu.set_a(7, pending.initial_sp);
        for (index, value) in pending.registers.data.into_iter().enumerate() {
            cpu.set_d(index, value);
        }
        for (index, value) in pending.registers.address.into_iter().enumerate() {
            cpu.set_a(index, value);
        }
        let result = cpu.run_batch(&mut loaded.memory, 4096, &[pending.return_pc]);
        assert_eq!(
            result.exit,
            m68k::BatchExit::WatchedPc {
                pc: pending.return_pc
            },
            "entry=${:08X} pc=${:08X} sp=${:08X} return=${:08X}",
            pending.entry,
            cpu.pc,
            cpu.a(7),
            pending.return_pc,
        );
        let result = match pending.result {
            None => None,
            Some(crate::guest_call::M68kResultSource::Data(index)) => {
                Some(cpu.d(usize::from(index)))
            }
            Some(crate::guest_call::M68kResultSource::Address(index)) => {
                Some(cpu.a(usize::from(index)))
            }
            Some(crate::guest_call::M68kResultSource::Memory { address, size }) => {
                Some(match size {
                    1 => u32::from(loaded.memory.read_u8(address).unwrap()),
                    2 => u32::from(loaded.memory.read_u16_be(address).unwrap()),
                    4 => loaded.memory.read_u32_be(address).unwrap(),
                    _ => panic!("unsupported 68k result size {size}"),
                })
            }
            Some(crate::guest_call::M68kResultSource::SpecialCase { selector, .. }) => {
                panic!("special-case result selector {selector} requires the shared runner")
            }
        };
        assert!(loaded
            .toolbox_startup
            .execution
            .calls()
            .complete_m68k_operation_for_powerpc(
            cpu.pc,
            cpu.a(7),
            result,
            &mut loaded.cpu,
            &mut loaded.memory,
            loaded.process_memory_manager.0.borrow_mut().native_mut(),
        ));

        if loaded.cpu.pc == PPC_GUEST_CALL_RETURN_PC
            || (loaded.cpu.pc >= loaded.import_trap_base
                && loaded.cpu.pc
                    < loaded
                        .import_trap_base
                        .saturating_add(loaded.import_count.saturating_mul(4)))
        {
            let probe = loaded.run_with_hle_imports(64);
            assert_eq!(probe.unsupported_import_index, None);
        }
    }
}

fn test_menu_resource(menu_id: i16, title: &[u8]) -> Vec<u8> {
    test_menu_resource_with_mdef(menu_id, 0, title)
}

fn test_menu_resource_with_mdef(menu_id: i16, mdef_id: i16, title: &[u8]) -> Vec<u8> {
    let mut data = vec![0; 14];
    data[0..2].copy_from_slice(&menu_id.to_be_bytes());
    data[6..8].copy_from_slice(&mdef_id.to_be_bytes());
    data[10..14].copy_from_slice(&u32::MAX.to_be_bytes());
    data.push(title.len() as u8);
    data.extend_from_slice(title);
    data.push(0);
    data
}

fn test_menu_color_entry(menu_id: i16, item: i16, seed: u8) -> [u8; 30] {
    let mut entry = [seed; 30];
    entry[0..2].copy_from_slice(&menu_id.to_be_bytes());
    entry[2..4].copy_from_slice(&item.to_be_bytes());
    entry
}

fn test_menu_color_resource(entries: &[[u8; 30]]) -> Vec<u8> {
    let mut data = i16::try_from(entries.len()).unwrap().to_be_bytes().to_vec();
    for entry in entries {
        data.extend_from_slice(entry);
    }
    data
}

fn install_test_menu(
    loaded: &mut PpcLoadedApp,
    scratch: u32,
    menu_id: i16,
    title: &[u8],
    item_specs: &[u8],
) -> u32 {
    let mut free_handle_blocks = loaded.free_handle_blocks();
    loaded.memory.add_region(scratch, vec![0; 0x200]);
    assert!(ppc_write_pstring_bytes(&mut loaded.memory, scratch, title));
    assert!(ppc_write_pstring_bytes(
        &mut loaded.memory,
        scratch + 0x80,
        item_specs,
    ));
    let menu = ppc_new_menu(
        &mut loaded.memory,
        test_heap_cursor!(loaded),
        test_heap_limit!(loaded),
        test_handles!(loaded),
        &mut free_handle_blocks,
        menu_id,
        scratch,
    );
    assert_ne!(menu, 0);
    if !item_specs.is_empty() {
        assert_eq!(
            ppc_insert_menu_items(
                &mut loaded.memory,
                test_heap_cursor!(loaded),
                test_heap_limit!(loaded),
                test_handles!(loaded),
                menu,
                scratch + 0x80,
                i16::MAX,
            ),
            PPC_NO_ERR,
        );
    }
    assert_eq!(
        ppc_insert_menu(
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            test_handles!(loaded),
            &mut free_handle_blocks,
            menu,
            0,
        ),
        PPC_NO_ERR,
    );
    menu
}

fn install_test_popup_menu(
    loaded: &mut PpcLoadedApp,
    scratch: u32,
    menu_id: i16,
    title: &[u8],
    item_specs: &[u8],
) -> u32 {
    let mut free_handle_blocks = loaded.free_handle_blocks();
    let menu = install_test_menu(loaded, scratch, menu_id, title, item_specs);
    let current_menu_list = ppc_current_menu_list(&mut loaded.memory);
    assert_eq!(
        ppc_delete_menu(
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            test_handles!(loaded),
            current_menu_list,
            menu_id,
        ),
        PPC_NO_ERR,
    );
    assert_eq!(
        ppc_insert_menu(
            &mut loaded.memory,
            test_heap_cursor!(loaded),
            test_heap_limit!(loaded),
            test_handles!(loaded),
            &mut free_handle_blocks,
            menu,
            -1,
        ),
        PPC_NO_ERR,
    );
    menu
}

fn draw_current_test_menu_bar(loaded: &mut PpcLoadedApp) -> bool {
    let menu_list = ppc_current_menu_list(&mut loaded.memory);
    let menu_color_bytes =
        ppc_menu_color_table_bytes(&mut loaded.memory, &test_handle_records!(loaded));
    ppc_draw_menu_bar_with_colors(
        &mut loaded.memory,
        &loaded.gworlds,
        menu_list,
        &loaded.screen_clut,
        MenuColorTable::new(&menu_color_bytes),
    )
}

pub(crate) struct CrossAbiMenuSelectFixture {
    pub(crate) app: PpcLoadedApp,
    pub(crate) root_menu: u32,
    pub(crate) root_record: u32,
    pub(crate) mdef_entry: u32,
    pub(crate) callback_marker: u32,
    pub(crate) title_h: i16,
}

pub(crate) fn cross_abi_menu_select_fixture() -> CrossAbiMenuSelectFixture {
    const ROOT_MENU_ID: i16 = 140;
    const CHILD_MENU_ID: i16 = 141;
    const TARGET_ITEM: i16 = 2;
    const MDEF_HANDLE: u32 = PPC_DATA_BASE + 0x7000;
    const MDEF_ENTRY: u32 = PPC_DATA_BASE + 0x7100;
    const CALLBACK_MARKER: u32 = PPC_DATA_BASE + 0x7200;
    const CALLBACK_VALUE: u32 = 0x68c0_ab1e;

    let pef = synthetic_pef_with_import(b"MenuSelect");
    let mut loaded = load_pef_application(&pef).unwrap();
    let root_menu = install_test_menu(
        &mut loaded,
        PPC_DATA_BASE + 0x1000,
        ROOT_MENU_ID,
        b"File",
        b"Custom child;Disabled after callback",
    );
    let child_menu = install_test_popup_menu(
        &mut loaded,
        PPC_DATA_BASE + 0x1400,
        CHILD_MENU_ID,
        b"Child",
        b"Choice",
    );

    loaded.cpu.gpr[3] = root_menu;
    loaded.cpu.gpr[4] = 1;
    loaded.cpu.gpr[5] = 0x1b;
    ppc_set_item_cmd(
        &loaded.cpu,
        &mut loaded.memory,
        &test_handle_records!(loaded),
    );
    loaded.cpu.gpr[5] = CHILD_MENU_ID as u32;
    ppc_set_item_mark(
        &loaded.cpu,
        &mut loaded.memory,
        &test_handle_records!(loaded),
    );

    let root_record = loaded.memory.read_u32_be(root_menu).unwrap();
    let child_record = loaded.memory.read_u32_be(child_menu).unwrap();
    loaded.memory.write_u16_be(child_record + 2, 72).unwrap();
    loaded.memory.write_u16_be(child_record + 4, 32).unwrap();
    loaded.memory.add_region(MDEF_HANDLE, vec![0; 4]);
    loaded.memory.add_region(CALLBACK_MARKER, vec![0; 4]);

    // The resource-backed MDEF is real 68k guest code. It pushes the
    // Pascal DisableItem(rootMenu, 2) arguments, executes the A-line, then
    // leaves a marker only after the trap returns and closes its own
    // 18-byte MenuDefProc argument frame.
    let mut mdef = Vec::new();
    mdef.extend_from_slice(&0x2f3cu16.to_be_bytes()); // MOVE.L #rootMenu,-(SP)
    mdef.extend_from_slice(&root_menu.to_be_bytes());
    mdef.extend_from_slice(&0x3f3cu16.to_be_bytes()); // MOVE.W #2,-(SP)
    mdef.extend_from_slice(&(TARGET_ITEM as u16).to_be_bytes());
    mdef.extend_from_slice(&0xa93au16.to_be_bytes()); // DisableItem
    mdef.extend_from_slice(&0x23fcu16.to_be_bytes()); // MOVE.L #value,marker
    mdef.extend_from_slice(&CALLBACK_VALUE.to_be_bytes());
    mdef.extend_from_slice(&CALLBACK_MARKER.to_be_bytes());
    mdef.extend_from_slice(&0x4e74u16.to_be_bytes()); // RTD #18
    mdef.extend_from_slice(&0x0012u16.to_be_bytes());
    loaded.memory.add_region(MDEF_ENTRY, mdef.clone());
    loaded.memory.write_u32_be(MDEF_HANDLE, MDEF_ENTRY).unwrap();
    loaded
        .memory
        .write_u32_be(child_record + 6, MDEF_HANDLE)
        .unwrap();
    let current_resource_refnum = *loaded.process_file_system.current_resource_file;
    loaded.process_file_system.push_vfs_resource(PpcVfsResourceRecord {
        ref_num: current_resource_refnum,
        path: "Cross-ABI menu fixture".to_string(),
        res_type: u32::from_be_bytes(*b"MDEF"),
        res_id: 512,
        name: Vec::new(),
        data: mdef,
        raw_data: None,
        raw_attrs: None,
        attrs: 0,
        handle: MDEF_HANDLE,
    });

    assert!(draw_current_test_menu_bar(&mut loaded));
    let title_h = STANDARD_MENU_BAR_FIRST_TITLE_LEFT + 2;
    loaded.cpu.gpr[3] = (u32::from(10u16) << 16) | u32::from(title_h as u16);

    CrossAbiMenuSelectFixture {
        app: loaded,
        root_menu,
        root_record,
        mdef_entry: MDEF_ENTRY,
        callback_marker: CALLBACK_MARKER,
        title_h,
    }
}

fn test_wind_resource(
    bounds: (i16, i16, i16, i16),
    proc_id: i16,
    visible: bool,
    go_away: bool,
    ref_con: u32,
    title: &[u8],
) -> Vec<u8> {
    let mut wind = Vec::with_capacity(19 + title.len());
    for coordinate in [bounds.0, bounds.1, bounds.2, bounds.3] {
        wind.extend_from_slice(&coordinate.to_be_bytes());
    }
    wind.extend_from_slice(&proc_id.to_be_bytes());
    wind.extend_from_slice(&u16::from(visible).to_be_bytes());
    wind.extend_from_slice(&u16::from(go_away).to_be_bytes());
    wind.extend_from_slice(&ref_con.to_be_bytes());
    wind.push(u8::try_from(title.len()).unwrap());
    wind.extend_from_slice(title);
    wind
}

#[test]
fn ppc_watch_parser_accepts_hex_address_and_optional_length() {
    assert_eq!(
        parse_ppc_watch_range_value(std::ffi::OsStr::new("0x02000000")),
        Some(PpcWatchRange {
            start: 0x0200_0000,
            len: 1
        })
    );
    assert_eq!(
        parse_ppc_watch_range_value(std::ffi::OsStr::new("$02000000:4")),
        Some(PpcWatchRange {
            start: 0x0200_0000,
            len: 4
        })
    );
    assert_eq!(
        parse_ppc_watch_range_value(std::ffi::OsStr::new("02000000:0x10")),
        Some(PpcWatchRange {
            start: 0x0200_0000,
            len: 16
        })
    );
}

#[test]
fn ppc_watch_parser_rejects_empty_zero_and_overflow_ranges() {
    assert_eq!(parse_ppc_watch_range_value(std::ffi::OsStr::new("")), None);
    assert_eq!(
        parse_ppc_watch_range_value(std::ffi::OsStr::new("02000000:0")),
        None
    );
    assert_eq!(
        parse_ppc_watch_range_value(std::ffi::OsStr::new("FFFFFFFF:2")),
        None
    );
    assert_eq!(
        parse_ppc_watch_range_value(std::ffi::OsStr::new("02000000:4:extra")),
        None
    );
}

#[test]
fn ppc_watch_range_contains_only_selected_bytes() {
    let range = PpcWatchRange {
        start: 0x0200_0002,
        len: 3,
    };

    assert!(!range.contains(0x0200_0001));
    assert!(range.contains(0x0200_0002));
    assert!(range.contains(0x0200_0004));
    assert!(!range.contains(0x0200_0005));
}

#[test]
fn ppc_watch_formatter_includes_context_and_written_byte() {
    let line = format_ppc_watch_write(PpcWatchWriteRecord {
        pc: 0x0100_0004,
        lr: 0x0100_0010,
        rtoc: 0x0200_0000,
        sp: 0x03fe_ffc0,
        addr: 0x0200_0002,
        value: 0xaa,
    });

    assert_eq!(
        line,
        "[PPC-WATCH] pc=$01000004 lr=$01000010 rtoc=$02000000 sp=$03FEFFC0 addr=$02000002 value=$AA"
    );
}

#[test]
fn ppc_trace_fetch_formatter_includes_pc_and_instruction_word() {
    assert_eq!(
        format_ppc_trace_fetch(0x0100_0004, 0x4e80_0020),
        "[PPC-TRACE] fetch pc=$01000004 word=$4E800020"
    );
}

#[test]
fn ppc_trace_import_formatter_includes_import_and_context() {
    let entry = PpcHleImportTraceEntry {
        import_index: 12,
        library_name: "InterfaceLib".to_string(),
        symbol_name: "NewPtrClear".to_string(),
        pc: 0x01f0_0030,
        lr: 0x0100_0010,
        rtoc: 0x0200_0000,
        sp: 0x03fe_ffc0,
        dispatcher_target: PpcImportDispatcherTarget::NewPtr { clear: true },
        repeat_count: 1,
    };

    assert_eq!(
        format_ppc_trace_import(&entry),
        "[PPC-TRACE] import #12 InterfaceLib:NewPtrClear pc=$01F00030 lr=$01000010 rtoc=$02000000 sp=$03FEFFC0 target=NewPtr { clear: true }"
    );
    assert_eq!(
        format_ppc_trace_unknown_import(13, 0x01f0_0034, 0x0100_0020, 0x0200_0004, 0x03fe_ffb0),
        "[PPC-TRACE] import #13 <unknown> pc=$01F00034 lr=$01000020 rtoc=$02000004 sp=$03FEFFB0"
    );
}

