#[test]
fn ppc_hand_to_hand_preserves_the_toolbox_color_table_fallback() {
    let pef = synthetic_pef_with_import(b"HandToHand");
    let mut native = load_pef_application(&pef).unwrap();
    ppc_seed_main_color_table(&mut native.memory).unwrap();
    let expected = ppc_memory_read_bytes(
        &mut native.memory,
        PPC_MAIN_CTABLE,
        PPC_MAIN_CTABLE_SIZE,
    )
    .unwrap();
    let handle_variable = PPC_DATA_BASE + 0x2100;
    native.memory.add_region(handle_variable, vec![0; 4]);
    native
        .memory
        .write_u32_be(handle_variable, PPC_MAIN_CTABLE_HANDLE)
        .unwrap();
    let mut context = ProcessContext::default();
    native.attach_unconverted_process_services(&mut context);
    let memory_manager = context.memory_manager_handle().clone();

    native.cpu.gpr[3] = handle_variable;
    run_test_import_with_process_memory_manager(
        &mut native,
        PpcImportDispatcherTarget::HandToHand,
        &memory_manager,
    );

    assert_eq!(native.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
    let copy_handle = native.memory.read_u32_be(handle_variable).unwrap();
    assert_ne!(copy_handle, PPC_MAIN_CTABLE_HANDLE);
    let copy = memory_manager
        .borrow()
        .native_allocation(copy_handle)
        .expect("Toolbox-owned data should retain the native fallback");
    assert_eq!(copy.size, PPC_MAIN_CTABLE_SIZE);
    assert_eq!(
        ppc_memory_read_bytes(&mut native.memory, copy.ptr, copy.size),
        Some(expected)
    );
    assert_eq!(memory_manager.borrow().state_for_handle(copy_handle), Some(0));
}

#[test]
fn ppc_hand_to_hand_color_table_heap_failure_is_atomic() {
    let pef = synthetic_pef_with_import(b"HandToHand");
    let mut native = load_pef_application(&pef).unwrap();
    ppc_seed_main_color_table(&mut native.memory).unwrap();
    let handle_variable = PPC_DATA_BASE + 0x2100;
    native.memory.add_region(handle_variable, vec![0; 4]);
    native
        .memory
        .write_u32_be(handle_variable, PPC_MAIN_CTABLE_HANDLE)
        .unwrap();
    let mut context = ProcessContext::default();
    native.attach_unconverted_process_services(&mut context);
    let memory_manager = context.memory_manager_handle().clone();
    let allocator_before = memory_manager
        .borrow()
        .native_allocator_snapshot()
        .expect("native allocator is attached");
    memory_manager
        .borrow_mut()
        .set_native_heap_limit(allocator_before.heap.heap_cursor + PPC_HEAP_ALIGNMENT);

    native.cpu.gpr[3] = handle_variable;
    run_test_import_with_process_memory_manager(
        &mut native,
        PpcImportDispatcherTarget::HandToHand,
        &memory_manager,
    );

    assert_eq!(native.cpu.gpr[3], ppc_i16_result(PPC_MEM_FULL_ERR));
    assert_eq!(
        native.memory.read_u32_be(handle_variable),
        Some(PPC_MAIN_CTABLE_HANDLE)
    );
    assert!(memory_manager.borrow().native_handle_records().is_empty());
    let allocator_after = memory_manager
        .borrow()
        .native_allocator_snapshot()
        .expect("native allocator remains attached");
    assert_eq!(allocator_after.heap.heap_cursor, allocator_before.heap.heap_cursor);
    assert_eq!(allocator_after.ptrs, allocator_before.ptrs);
    assert_eq!(allocator_after.free_ptr_blocks, allocator_before.free_ptr_blocks);
    assert_eq!(
        allocator_after.free_handle_blocks,
        allocator_before.free_handle_blocks
    );
    assert_eq!(allocator_after.heap.last_mem_error, PPC_MEM_FULL_ERR);
}

#[test]
fn native_menu_flash_accessors_use_the_live_low_memory_word() {
    let pef = synthetic_pef_with_import(b"SetMenuFlash");
    let mut loaded = load_pef_application(&pef).unwrap();
    assert_eq!(
        loaded
            .memory
            .read_u16_be(crate::memory::globals::addr::MENU_FLASH),
        Some(crate::memory::globals::DEFAULT_MENU_FLASH_COUNT)
    );

    loaded.cpu.gpr[3] = 0xcafe_0001;
    run_test_import(&mut loaded, PpcImportDispatcherTarget::SetMenuFlash);
    assert_eq!(loaded.cpu.gpr[3], 0xcafe_0001);
    assert_eq!(
        loaded
            .memory
            .read_u16_be(crate::memory::globals::addr::MENU_FLASH),
        Some(1)
    );

    loaded.cpu.gpr[3] = 0xdead_beef;
    run_test_import(&mut loaded, PpcImportDispatcherTarget::LMGetMenuFlash);
    assert_eq!(loaded.cpu.gpr[3], 1);

    loaded
        .memory
        .write_u16_be(crate::memory::globals::addr::MENU_FLASH, u16::MAX)
        .unwrap();
    run_test_import(&mut loaded, PpcImportDispatcherTarget::LMGetMenuFlash);
    assert_eq!(loaded.cpu.gpr[3], u32::MAX);
}

#[test]
fn native_insert_and_append_res_menu_share_resource_name_policy() {
    let pef = synthetic_pef_with_import(b"InsertResMenu");
    let mut loaded = load_pef_application(&pef).unwrap();
    let menu = install_test_menu(
        &mut loaded,
        PPC_DATA_BASE + 0x1000,
        128,
        b"Apple",
        b"Existing;Tail",
    );
    let current = *loaded.process_file_system.current_resource_file;
    let record = |ref_num, res_id, name: &[u8], byte| PpcVfsResourceRecord {
        ref_num,
        path: format!("Resources {ref_num}"),
        res_type: u32::from_be_bytes(*b"DRVR"),
        res_id,
        name: name.to_vec(),
        data: vec![byte],
        raw_data: None,
        raw_attrs: None,
        attrs: 0,
        handle: 0,
    };
    loaded.process_file_system.extend_vfs_resources([
        record(current, 103, b"Zulu", 1),
        record(current, 104, b"Alpha", 2),
        record(current, 105, b".Hidden", 3),
        record(current, 106, b"Existing", 4),
        record(2, 103, b"Shadowed", 5),
        record(2, 107, b"Beta", 6),
    ]);
    loaded.policy.set_res_load(false);
    loaded.cpu.gpr[3] = menu;
    loaded.cpu.gpr[4] = u32::from_be_bytes(*b"DRVR");
    loaded.cpu.gpr[5] = 1;
    run_test_import(&mut loaded, PpcImportDispatcherTarget::InsertResMenu);

    let items = ppc_menu_items_from_memory(&mut loaded.memory, menu).unwrap();
    assert_eq!(
        items
            .items
            .iter()
            .map(|item| item.text.as_slice())
            .collect::<Vec<_>>(),
        [
            b"Existing".as_slice(),
            b"Alpha".as_slice(),
            b"Beta".as_slice(),
            b"Zulu".as_slice(),
            b"Tail".as_slice(),
        ]
    );
    for item in &items.items[1..4] {
        assert!(item.enabled);
        assert_eq!(
            (item.icon, item.command, item.mark, item.style),
            (0, 0, 0, 0)
        );
    }
    assert!(loaded.policy.res_load());
    for resource in &loaded.process_file_system.vfs_resources {
        if resource.name == b"Shadowed" {
            assert_eq!(
                resource.handle, 0,
                "closer type/ID must shadow this resource"
            );
        } else {
            assert_ne!(resource.handle, 0, "matching resources must be loaded");
            assert_ne!(loaded.memory.read_u32_be(resource.handle), Some(0));
        }
    }

    loaded.process_file_system.push_vfs_resource(record(2, 108, b"Gamma", 7));
    loaded.cpu.gpr[3] = menu;
    loaded.cpu.gpr[4] = u32::from_be_bytes(*b"DRVR");
    run_test_import(&mut loaded, PpcImportDispatcherTarget::AppendResMenu);
    assert_eq!(
        ppc_menu_items_from_memory(&mut loaded.memory, menu)
            .unwrap()
            .items
            .iter()
            .map(|item| item.text.as_slice())
            .collect::<Vec<_>>(),
        [
            b"Existing".as_slice(),
            b"Alpha".as_slice(),
            b"Beta".as_slice(),
            b"Zulu".as_slice(),
            b"Tail".as_slice(),
            b"Gamma".as_slice(),
        ]
    );
    assert_eq!(loaded.last_mem_error(), PPC_NO_ERR);
}

#[test]
fn native_append_res_menu_gives_fond_names_precedence_and_adds_builtin_fonts() {
    let pef = synthetic_pef_with_import(b"AppendResMenu");
    let mut loaded = load_pef_application(&pef).unwrap();
    let menu = install_test_menu(&mut loaded, PPC_DATA_BASE + 0x1000, 129, b"Font", b"");
    let current = *loaded.process_file_system.current_resource_file;
    loaded.process_file_system.extend_vfs_resources([
        PpcVfsResourceRecord {
            ref_num: current,
            path: "Test App".to_string(),
            res_type: u32::from_be_bytes(*b"FONT"),
            res_id: 7,
            name: b"Custom Face".to_vec(),
            data: vec![1],
            raw_data: None,
            raw_attrs: None,
            attrs: 0,
            handle: 0,
        },
        PpcVfsResourceRecord {
            ref_num: current,
            path: "Test App".to_string(),
            res_type: u32::from_be_bytes(*b"FOND"),
            res_id: 8,
            name: b"Custom Face".to_vec(),
            data: vec![2],
            raw_data: None,
            raw_attrs: None,
            attrs: 0,
            handle: 0,
        },
    ]);

    loaded.cpu.gpr[3] = menu;
    loaded.cpu.gpr[4] = u32::from_be_bytes(*b"FONT");
    run_test_import(&mut loaded, PpcImportDispatcherTarget::AppendResMenu);

    let names = ppc_menu_items_from_memory(&mut loaded.memory, menu)
        .unwrap()
        .items
        .into_iter()
        .map(|item| item.text)
        .collect::<Vec<_>>();
    assert_eq!(
        names
            .iter()
            .filter(|name| name.as_slice() == b"Custom Face")
            .count(),
        1,
        "the FOND name must suppress the later FONT duplicate"
    );
    for expected in [b"Chicago".as_slice(), b"Geneva", b"Monaco", b"New York"] {
        assert!(names.iter().any(|name| name == expected));
    }
    assert!(!names.iter().any(|name| name == b"Application"));
    assert!(loaded
        .vfs_resources
        .iter()
        .all(|resource| resource.handle != 0));
}

#[test]
fn hle_import_runner_menu_choice_returns_menu_disable_without_side_effects() {
    let pef = synthetic_pef_with_import(b"MenuChoice");
    let mut loaded = load_pef_application(&pef).unwrap();
    let original_sp = loaded.cpu.gpr[1];

    for expected in [0, (128u32 << 16) | 3, (201u32 << 16) | 0xffff] {
        loaded
            .memory
            .write_u32_be(crate::memory::globals::addr::MENU_DISABLE, expected)
            .unwrap();
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = 0xdead_beef;

        let probe = loaded.run_with_hle_imports(64);

        assert!(matches!(probe.result, PpcRunResult::Halted { .. }));
        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], expected);
        assert_eq!(loaded.cpu.gpr[1], original_sp);
        assert_eq!(
            loaded
                .memory
                .read_u32_be(crate::memory::globals::addr::MENU_DISABLE),
            Some(expected),
        );
    }
}

// The native standard MDEF must update the same live MenuDisable value as
// the 68k tracker even though a disabled row cannot become MenuSelect's
// highlighted result. Inside Macintosh Volume V (1986), pp. V-235 and
// V-248--V-249; Macintosh Toolbox Essentials (1992), pp. 3-118--3-119.
#[test]
fn native_menuselect_disabled_item_updates_live_menuchoice_result() {
    let pef = synthetic_pef_with_import(b"MenuSelect");
    let mut loaded = load_pef_application(&pef).unwrap();
    let menu = install_test_menu(&mut loaded, PPC_DATA_BASE + 0x1000, 128, b"File", b"Open/O");
    ppc_set_menu_item_enabled(
        &mut loaded.memory,
        &test_handle_records!(loaded),
        menu,
        1,
        false,
    );
    assert!(draw_current_test_menu_bar(&mut loaded));

    let title_h = STANDARD_MENU_BAR_FIRST_TITLE_LEFT + 2;
    loaded.cpu.gpr[3] = (u32::from(10u16) << 16) | u32::from(title_h as u16);
    loaded.set_input_snapshot(PpcInputSnapshot {
        mouse_button: true,
        mouse_v: 10,
        mouse_h: title_h,
        ..PpcInputSnapshot::default()
    });
    assert!(matches!(
        loaded.run_with_hle_imports(64).result,
        PpcRunResult::CycleLimit { .. }
    ));
    let tracking = loaded.toolbox_startup.execution.menu().snapshot().unwrap();

    loaded.set_input_snapshot(PpcInputSnapshot {
        mouse_button: false,
        mouse_v: tracking.popup_top + 6,
        mouse_h: tracking.popup_left + 4,
        ..PpcInputSnapshot::default()
    });
    let probe = loaded.run_with_hle_imports(64);
    assert!(matches!(probe.result, PpcRunResult::Halted { .. }));
    assert_eq!(loaded.cpu.gpr[3], 0);
    assert!(loaded.toolbox_startup.execution.menu().is_none());

    let expected = menu_choice_value(128, 1);
    assert_eq!(
        loaded
            .memory
            .read_u32_be(crate::memory::globals::addr::MENU_DISABLE),
        Some(expected),
    );
    loaded.cpu.gpr[3] = 0xDEAD_BEEF;
    run_test_import(&mut loaded, PpcImportDispatcherTarget::MenuChoice);
    assert_eq!(loaded.cpu.gpr[3], expected);
}

