    loaded.cpu.gpr[2] = caller_rtoc;
    loaded.cpu.gpr[3] = descriptor;
    loaded.cpu.gpr[4] = proc_info;
    loaded.cpu.gpr[5] = 0xabcd_7654;
    loaded.cpu.gpr[6] = 0xcafe_babe;
    loaded.cpu.gpr[7] = 0x1234_56ee;

