    loaded.cpu.pc = loaded.entry_pc;
    loaded.cpu.lr = PPC_HALT_PC;
    loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::Q3InterpolationStyleNew;
    loaded.cpu.gpr[3] = 1;

