#[test]
fn hle_import_runner_handles_qa_engine_gestalt() {
    let pef =
        synthetic_pef_with_library_import(b"QuickDraw\xaa 3D Accelerator", b"QAEngineGestalt");
    let mut loaded = load_pef_application(&pef).unwrap();
    let response_ptr = PPC_DATA_BASE + 0x1000;
    loaded.memory.add_region(response_ptr, vec![0xaa; 64]);
    loaded.cpu.gpr[3] = PPC_QA_ENGINE;
    loaded.cpu.gpr[4] = 0;
    loaded.cpu.gpr[5] = response_ptr;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], 0);
    assert_eq!(
        loaded.memory.read_u32_be(response_ptr),
        Some(ppc_qa_optional_features())
    );

    for (selector, expected) in [
        (1, ppc_qa_fast_features()),
        (2, PPC_QA_VENDOR_APPLE),
        (3, PPC_QA_ENGINE_APPLE_SW),
        (4, 1),
        (5, PPC_QA_ENGINE_NAME.len() as u32),
        (7, PPC_QA_AVAILABLE_TEXTURE_MEMORY),
        (42, 0),
    ] {
        let mut loaded = load_pef_application(&pef).unwrap();
        loaded.memory.add_region(response_ptr, vec![0xaa; 4]);
        loaded.cpu.gpr[3] = PPC_QA_ENGINE;
        loaded.cpu.gpr[4] = selector;
        loaded.cpu.gpr[5] = response_ptr;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1, "selector {selector}");
        assert_eq!(probe.unsupported_import_index, None, "selector {selector}");
        assert_eq!(loaded.cpu.gpr[3], 0, "selector {selector}");
        assert_eq!(
            loaded.memory.read_u32_be(response_ptr),
            Some(expected),
            "selector {selector}"
        );
    }

    let mut loaded = load_pef_application(&pef).unwrap();
    loaded.memory.add_region(response_ptr, vec![0xaa; 64]);
    loaded.cpu.gpr[3] = PPC_QA_ENGINE;
    loaded.cpu.gpr[4] = 6;
    loaded.cpu.gpr[5] = response_ptr;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], 0);
    for (offset, byte) in PPC_QA_ENGINE_NAME.iter().copied().enumerate() {
        assert_eq!(
            loaded.memory.read_u8(response_ptr + offset as u32),
            Some(byte)
        );
    }
    assert_eq!(
        loaded
            .memory
            .read_u8(response_ptr + PPC_QA_ENGINE_NAME.len() as u32),
        Some(0)
    );

    let mut loaded = load_pef_application(&pef).unwrap();
    let short_word_response_ptr = PPC_DATA_BASE + 0x1100;
    loaded
        .memory
        .add_region(short_word_response_ptr, vec![0xee; 2]);
    loaded.cpu.gpr[3] = PPC_QA_ENGINE;
    loaded.cpu.gpr[4] = 0;
    loaded.cpu.gpr[5] = short_word_response_ptr;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PARAM_ERR));
    assert_eq!(loaded.memory.read_u8(short_word_response_ptr), Some(0xee));
    assert_eq!(
        loaded.memory.read_u8(short_word_response_ptr + 1),
        Some(0xee)
    );

    let mut loaded = load_pef_application(&pef).unwrap();
    let short_name_response_ptr = PPC_DATA_BASE + 0x1200;
    loaded
        .memory
        .add_region(short_name_response_ptr, vec![0xdd; 4]);
    loaded.cpu.gpr[3] = PPC_QA_ENGINE;
    loaded.cpu.gpr[4] = 6;
    loaded.cpu.gpr[5] = short_name_response_ptr;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PARAM_ERR));
    assert_eq!(
        loaded.memory.read_u32_be(short_name_response_ptr),
        Some(0xdddd_dddd)
    );

    let mut loaded = load_pef_application(&pef).unwrap();
    let invalid_engine_response_ptr = PPC_DATA_BASE + 0x1300;
    loaded
        .memory
        .add_region(invalid_engine_response_ptr, vec![0xcc; 4]);
    loaded.cpu.gpr[3] = PPC_QA_ENGINE + 4;
    loaded.cpu.gpr[4] = 0;
    loaded.cpu.gpr[5] = invalid_engine_response_ptr;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PARAM_ERR));
    assert_eq!(
        loaded.memory.read_u32_be(invalid_engine_response_ptr),
        Some(0xcccc_cccc)
    );

    let mut loaded = load_pef_application(&pef).unwrap();
    loaded.cpu.gpr[3] = PPC_QA_ENGINE;
    loaded.cpu.gpr[4] = 0;
    loaded.cpu.gpr[5] = 0;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PARAM_ERR));
}

#[test]
fn hle_import_runner_tracks_quicktime_init_and_error_state() {
    let pef = synthetic_pef_with_library_import(b"QuickTimeLib", b"EnterMovies");
    let mut loaded = load_pef_application(&pef).unwrap();
    loaded.cpu.gpr[3] = 0xfeed_face;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));
    assert_eq!(loaded.quicktime.movie_toolbox_enter_count, 1);
    assert_eq!(loaded.quicktime.movie_toolbox_exit_count, 0);
    assert_eq!(loaded.quicktime.movie_toolbox_init_depth, 1);
    assert_eq!(loaded.quicktime.movie_error, PPC_NO_ERR);
    assert_eq!(loaded.quicktime.movie_sticky_error, PPC_NO_ERR);

    loaded.cpu.pc = loaded.entry_pc;
    loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::QtGraphicsImportSetGWorld;
    loaded.cpu.gpr[3] = 0;
    loaded.cpu.gpr[4] = 0x0600_3000;
    loaded.cpu.gpr[5] = 0x0600_4000;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PARAM_ERR));
    assert_eq!(loaded.quicktime.movie_error, PPC_PARAM_ERR);
    assert_eq!(loaded.quicktime.movie_sticky_error, PPC_PARAM_ERR);

    loaded.cpu.pc = loaded.entry_pc;
    loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::QtGetMoviesError;
    loaded.cpu.gpr[3] = 0;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PARAM_ERR));
    assert_eq!(loaded.quicktime.movie_error, PPC_NO_ERR);
    assert_eq!(loaded.quicktime.movie_sticky_error, PPC_PARAM_ERR);

    loaded.cpu.pc = loaded.entry_pc;
    loaded.cpu.gpr[3] = 0;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));

    loaded.cpu.pc = loaded.entry_pc;
    loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::QtGetMoviesStickyError;
    loaded.cpu.gpr[3] = 0;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_PARAM_ERR));
    assert_eq!(loaded.quicktime.movie_error, PPC_NO_ERR);
    assert_eq!(loaded.quicktime.movie_sticky_error, PPC_PARAM_ERR);

    loaded.cpu.pc = loaded.entry_pc;
    loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::QtClearMoviesStickyError;
    loaded.cpu.gpr[3] = 0xfeed_face;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], 0xfeed_face);
    assert_eq!(loaded.quicktime.movie_error, PPC_NO_ERR);
    assert_eq!(loaded.quicktime.movie_sticky_error, PPC_NO_ERR);

    loaded.cpu.pc = loaded.entry_pc;
    loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::QtExitMovies;
    loaded.cpu.gpr[3] = 0xcafe_babe;

    let probe = loaded.run_with_hle_imports(64);

    assert_eq!(probe.handled_import_count, 1);
    assert_eq!(probe.unsupported_import_index, None);
    assert_eq!(loaded.cpu.gpr[3], 0xcafe_babe);
    assert_eq!(loaded.quicktime.movie_toolbox_enter_count, 1);
    assert_eq!(loaded.quicktime.movie_toolbox_exit_count, 1);
    assert_eq!(loaded.quicktime.movie_toolbox_init_depth, 0);
}

