#[test]
fn hle_import_runner_popup_menu_select_tracks_flashes_and_preserves_abi() {
    let pef = synthetic_pef_with_import(b"PopUpMenuSelect");
    let mut loaded = load_pef_application(&pef).unwrap();
    let menu_handle = install_test_popup_menu(
        &mut loaded,
        PPC_DATA_BASE + 0x1000,
        300,
        b"Popup",
        b"Red;Orange",
    );
    let front =
        ppc_front_buffer_for_gworld(&loaded.gworlds, PPC_MAIN_GWORLD).expect("main buffer");
    let framebuffer_len = front.row_bytes * front.height;
    let pattern = (0..usize::try_from(framebuffer_len).unwrap())
        .map(|index| (index as u8).wrapping_mul(37) ^ 0xa5)
        .collect::<Vec<_>>();
    loaded
        .memory
        .write_bytes(front.base_addr, &pattern)
        .unwrap();
    loaded
        .memory
        .write_u16_be(PPC_THE_MENU_ADDR, 0x2468)
        .unwrap();
    let menu_bar_len = 20 * front.row_bytes;
    let menu_bar_before =
        ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, menu_bar_len).unwrap();
    let before =
        ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, framebuffer_len).unwrap();

    loaded.cpu.gpr[3] = menu_handle;
    loaded.cpu.gpr[4] = 100;
    loaded.cpu.gpr[5] = 50;
    loaded.cpu.gpr[6] = 2;
    let original_sp = loaded.cpu.gpr[1];
    let original_args = [loaded.cpu.gpr[4], loaded.cpu.gpr[5], loaded.cpu.gpr[6]];
    loaded.set_input_snapshot(PpcInputSnapshot {
        mouse_button: true,
        mouse_v: 0,
        mouse_h: 0,
        ..PpcInputSnapshot::default()
    });

    let tick = loaded.current_tick().wrapping_add(1);
    loaded.set_tick_count(tick);
    let probe = loaded.run_with_hle_imports(64);

    assert!(matches!(probe.result, PpcRunResult::CycleLimit { .. }));
    assert_eq!(loaded.cpu.pc, PPC_GUEST_CALL_RETURN_PC);
    assert_eq!(loaded.cpu.gpr[1], original_sp);
    assert_eq!(loaded.cpu.gpr[3], menu_handle);
    assert_eq!(
        [loaded.cpu.gpr[4], loaded.cpu.gpr[5], loaded.cpu.gpr[6]],
        original_args
    );
    let tracking = loaded.toolbox_startup.execution.menu().snapshot().unwrap();
    let parked_lr = loaded.cpu.lr;
    assert_eq!(tracking.kind, MenuTrackingKind::PopUp);
    assert_eq!(
        loaded.toolbox_startup.execution.menu().context().native_popup(),
        Some(MenuTrackingCall {
            request: MenuTrackingRequest::PopUp(PopupMenuRequest {
                menu_handle,
                anchor: (100, 50),
                requested_item: 2,
            }),
            origin: MenuTrackingOrigin::PowerPc { stack_pointer: original_sp, return_address: parked_lr },
        })
    );
    assert_eq!(tracking.popup_left, 50);
    assert_eq!(tracking.popup_top + 16, 100);
    assert_eq!(tracking.highlighted_item, 2);
    let black =
        ppc_physical_screen_color_pixel(front, PPC_RGB_BLACK, &loaded.screen_clut).unwrap();
    let white =
        ppc_physical_screen_color_pixel(front, PPC_RGB_WHITE, &loaded.screen_clut).unwrap();
    assert_eq!(
        ppc_quickdraw_read_pixel(
            &mut loaded.memory,
            front,
            (i32::from(tracking.popup_left + 4), 100),
        ),
        Some(black),
        "requested item did not begin at Top"
    );
    assert_eq!(
        ppc_quickdraw_read_pixel(
            &mut loaded.memory,
            front,
            (i32::from(tracking.popup_left + 4), 99),
        ),
        Some(white),
        "row above requested item was also highlighted"
    );
    assert_ne!(
        ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, framebuffer_len),
        Some(before.clone())
    );
    assert_eq!(loaded.memory.read_u16_be(PPC_THE_MENU_ADDR), Some(0x2468));

    let item_one = PpcInputSnapshot {
        mouse_button: true,
        mouse_v: tracking.popup_top + 6,
        mouse_h: tracking.popup_left + 4,
        ..PpcInputSnapshot::default()
    };
    loaded.set_input_snapshot(item_one);
    let tick = loaded.current_tick().wrapping_add(1);
    loaded.set_tick_count(tick);
    let probe = loaded.run_with_hle_imports(64);
    assert!(matches!(probe.result, PpcRunResult::CycleLimit { .. }));
    assert_eq!(loaded.cpu.lr, parked_lr);
    assert_eq!(loaded.cpu.gpr[1], original_sp);
    assert_eq!(
        loaded
            .toolbox_startup
            .execution.menu()
            .as_ref()
            .unwrap()
            .highlighted_item,
        1
    );

    let item_two_release = PpcInputSnapshot {
        mouse_button: false,
        mouse_v: tracking.popup_top + 16 + 4,
        mouse_h: tracking.popup_left + 4,
        ..PpcInputSnapshot::default()
    };
    loaded
        .memory
        .write_u16_be(crate::memory::globals::addr::MENU_FLASH, 1)
        .unwrap();
    loaded.set_input_snapshot(item_two_release);
    let tick = loaded.current_tick().wrapping_add(1);
    loaded.set_tick_count(tick);
    let probe = loaded.run_with_hle_imports(64);
    assert!(matches!(probe.result, PpcRunResult::CycleLimit { .. }));
    let flash = loaded.toolbox_startup.execution.menu().as_ref().unwrap();
    assert_eq!(flash.flash_remaining, 2);
    assert_eq!(flash.highlighted_item, 2);
    assert_eq!(flash.flash_result, (300u32 << 16) | 2);

    let flash_probe = (
        i32::from(tracking.popup_left + 4),
        i32::from(tracking.popup_top + 16 + 4),
    );
    let mut flash_pixels =
        vec![ppc_quickdraw_read_pixel(&mut loaded.memory, front, flash_probe).unwrap()];
    let mut final_probe = None;
    for _ in 0..32 {
        let tick = loaded.current_tick().wrapping_add(1);
        loaded.set_tick_count(tick);
        let probe = loaded.run_with_hle_imports(64);
        if loaded.toolbox_startup.execution.menu().is_some() {
            flash_pixels.push(
                ppc_quickdraw_read_pixel(&mut loaded.memory, front, flash_probe).unwrap(),
            );
        } else {
            final_probe = Some(probe);
            break;
        }
    }
    let final_probe = final_probe.expect("popup flash completed");
    assert!(matches!(
        final_probe.result,
        PpcRunResult::Halted {
            pc: PPC_HALT_PC,
            ..
        }
    ));
    assert_eq!(loaded.cpu.gpr[3], (300u32 << 16) | 2);
    assert!(flash_pixels.contains(&black));
    assert!(flash_pixels.contains(&white));
    assert_eq!(
        ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, framebuffer_len),
        Some(before)
    );
    assert_eq!(
        ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, menu_bar_len),
        Some(menu_bar_before)
    );
    assert_eq!(loaded.memory.read_u16_be(PPC_THE_MENU_ADDR), Some(0x2468));
}

#[test]
fn hle_import_runner_popup_menu_select_no_hit_paths_are_atomic() {
    let pef = synthetic_pef_with_import(b"PopUpMenuSelect");
    let mut loaded = load_pef_application(&pef).unwrap();
    let menu_handle = install_test_popup_menu(
        &mut loaded,
        PPC_DATA_BASE + 0x1000,
        300,
        b"Popup",
        b"First;Second",
    );
    let front = ppc_front_buffer_for_gworld(&loaded.gworlds, PPC_MAIN_GWORLD).unwrap();
    let framebuffer_len = front.row_bytes * front.height;
    let before =
        ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, framebuffer_len).unwrap();
    loaded
        .memory
        .write_u16_be(PPC_THE_MENU_ADDR, 0x1357)
        .unwrap();
    loaded.cpu.gpr[3] = menu_handle;
    loaded.cpu.gpr[4] = 100;
    loaded.cpu.gpr[5] = 50;
    loaded.cpu.gpr[6] = 1;
    loaded.set_input_snapshot(PpcInputSnapshot {
        mouse_v: 100,
        mouse_h: 50,
        ..PpcInputSnapshot::default()
    });

    let probe = loaded.run_with_hle_imports(64);

    assert!(matches!(probe.result, PpcRunResult::Halted { .. }));
    assert_eq!(loaded.cpu.gpr[3], 0);
    assert!(loaded.toolbox_startup.execution.menu().is_none());
    assert_eq!(
        ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, framebuffer_len),
        Some(before)
    );
    assert_eq!(loaded.memory.read_u16_be(PPC_THE_MENU_ADDR), Some(0x1357));

    let mut miss = load_pef_application(&pef).unwrap();
    let regular_menu =
        install_test_menu(&mut miss, PPC_DATA_BASE + 0x1000, 304, b"Regular", b"First");
    let front = ppc_front_buffer_for_gworld(&miss.gworlds, PPC_MAIN_GWORLD).unwrap();
    let framebuffer_len = front.row_bytes * front.height;
    let before =
        ppc_memory_read_bytes(&mut miss.memory, front.base_addr, framebuffer_len).unwrap();
    for (label, menu_handle) in [
        ("invalid handle", 0xdead_beef),
        ("menu outside hierarchical list", regular_menu),
    ] {
        miss.cpu.pc = miss.entry_pc;
        miss.cpu.lr = PPC_HALT_PC;
        miss.cpu.gpr[3] = menu_handle;
        miss.cpu.gpr[4] = 100;
        miss.cpu.gpr[5] = 50;
        miss.cpu.gpr[6] = 1;
        miss.set_input_snapshot(PpcInputSnapshot {
            mouse_button: true,
            mouse_v: 100,
            mouse_h: 50,
            ..PpcInputSnapshot::default()
        });

        let probe = miss.run_with_hle_imports(64);

        assert!(
            matches!(probe.result, PpcRunResult::Halted { .. }),
            "{label}"
        );
        assert_eq!(miss.cpu.gpr[3], 0, "{label}");
        assert!(miss.toolbox_startup.execution.menu().is_none(), "{label}");
        assert_eq!(
            ppc_memory_read_bytes(&mut miss.memory, front.base_addr, framebuffer_len),
            Some(before.clone()),
            "{label}"
        );
    }

    for (label, item_specs) in [
        ("disabled item", b"First;Disabled(".as_slice()),
        ("separator", b"First;-".as_slice()),
    ] {
        let mut loaded = load_pef_application(&pef).unwrap();
        let menu_handle = install_test_popup_menu(
            &mut loaded,
            PPC_DATA_BASE + 0x1000,
            301,
            b"Popup",
            item_specs,
        );
        let front = ppc_front_buffer_for_gworld(&loaded.gworlds, PPC_MAIN_GWORLD).unwrap();
        let framebuffer_len = front.row_bytes * front.height;
        let before =
            ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, framebuffer_len)
                .unwrap();
        loaded
            .memory
            .write_u16_be(PPC_THE_MENU_ADDR, 0x1357)
            .unwrap();
        loaded.cpu.gpr[3] = menu_handle;
        loaded.cpu.gpr[4] = 100;
        loaded.cpu.gpr[5] = 50;
        loaded.cpu.gpr[6] = 1;
        loaded.set_input_snapshot(PpcInputSnapshot {
            mouse_button: true,
            mouse_v: 0,
            mouse_h: 0,
            ..PpcInputSnapshot::default()
        });
        let probe = loaded.run_with_hle_imports(64);
        assert!(matches!(probe.result, PpcRunResult::CycleLimit { .. }));
        let tracking = loaded.toolbox_startup.execution.menu().snapshot().unwrap();
        loaded.set_input_snapshot(PpcInputSnapshot {
            mouse_button: false,
            mouse_v: tracking.popup_top + 16 + 4,
            mouse_h: tracking.popup_left + 4,
            ..PpcInputSnapshot::default()
        });

        let probe = loaded.run_with_hle_imports(64);

        assert!(
            matches!(probe.result, PpcRunResult::Halted { .. }),
            "{label}"
        );
        assert_eq!(loaded.cpu.gpr[3], 0, "{label}");
        assert!(loaded.toolbox_startup.execution.menu().is_none(), "{label}");
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, framebuffer_len),
            Some(before),
            "{label}"
        );
        assert_eq!(loaded.memory.read_u16_be(PPC_THE_MENU_ADDR), Some(0x1357));
    }
}

#[test]
fn hle_import_runner_popup_menu_select_round_trips_supported_depths_and_clamps() {
    let pef = synthetic_pef_with_import(b"PopUpMenuSelect");
    let mut loaded = load_pef_application(&pef).unwrap();
    let menu_handle = install_test_popup_menu(
        &mut loaded,
        PPC_DATA_BASE + 0x1000,
        302,
        b"Popup",
        b"One;Two;Three",
    );
    loaded.toolbox_startup.host_menu_bar_hidden = true;

    for depth in [1, 2, 4, 8, 16] {
        loaded.cpu.gpr[3] = PPC_MAIN_GDEVICE;
        loaded.cpu.gpr[4] = depth;
        loaded.cpu.gpr[5] = 1;
        loaded.cpu.gpr[6] = u32::from(depth != 1);
        run_test_import(&mut loaded, PpcImportDispatcherTarget::SetDepth);
        assert_eq!(loaded.cpu.gpr[3], ppc_i16_result(PPC_NO_ERR));

        let front = ppc_live_front_buffer_for_gworld(
            &mut loaded.memory,
            &loaded.gworlds,
            PPC_MAIN_GWORLD,
        )
        .unwrap();
        let framebuffer_len = front.row_bytes * front.height;
        let pattern = (0..usize::try_from(framebuffer_len).unwrap())
            .map(|index| (index as u8).wrapping_mul(29).wrapping_add(depth as u8) ^ 0x96)
            .collect::<Vec<_>>();
        loaded
            .memory
            .write_bytes(front.base_addr, &pattern)
            .unwrap();
        loaded
            .memory
            .write_u16_be(PPC_THE_MENU_ADDR, 0x55aa)
            .unwrap();
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::PopUpMenuSelect;
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = menu_handle;
        loaded.cpu.gpr[4] = i16::MAX as u32;
        loaded.cpu.gpr[5] = i16::MAX as u32;
        loaded.cpu.gpr[6] = 3;
        loaded.set_input_snapshot(PpcInputSnapshot {
            mouse_button: true,
            mouse_v: 0,
            mouse_h: 0,
            ..PpcInputSnapshot::default()
        });

        let probe = loaded.run_with_hle_imports(64);

        assert!(matches!(probe.result, PpcRunResult::CycleLimit { .. }));
        let tracking = loaded.toolbox_startup.execution.menu().snapshot().unwrap();
        assert_eq!(tracking.kind, MenuTrackingKind::PopUp);
        assert_eq!(
            loaded.toolbox_startup.execution.menu().context().native_popup(),
            Some(ppc_popup_menu_call(&loaded.cpu))
        );
        assert_eq!(
            i32::from(tracking.popup_left) + i32::from(tracking.saved_width),
            i32::try_from(front.width).unwrap() - 3,
            "{depth}bpp popup did not clamp its right shadow to the screen"
        );
        assert_eq!(
            i32::from(tracking.popup_top) + i32::from(tracking.saved_height),
            i32::try_from(front.height).unwrap(),
            "{depth}bpp popup did not clamp its shadow to the screen"
        );
        assert_ne!(
            ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, framebuffer_len),
            Some(pattern.clone()),
            "{depth}bpp popup did not draw"
        );

        loaded.set_input_snapshot(PpcInputSnapshot {
            mouse_button: false,
            mouse_v: tracking.popup_top + 4,
            mouse_h: tracking.popup_left - 1,
            ..PpcInputSnapshot::default()
        });
        let probe = loaded.run_with_hle_imports(64);

        assert!(matches!(probe.result, PpcRunResult::Halted { .. }));
        assert_eq!(loaded.cpu.gpr[3], 0);
        assert!(loaded.toolbox_startup.execution.menu().is_none());
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, front.base_addr, framebuffer_len),
            Some(pattern),
            "{depth}bpp popup did not restore framebuffer and row padding"
        );
        assert_eq!(loaded.memory.read_u16_be(PPC_THE_MENU_ADDR), Some(0x55aa));
    }
}

#[test]
fn hle_import_runner_popup_menu_select_tracks_oversized_content_from_shared_layout() {
    let pef = synthetic_pef_with_import(b"PopUpMenuSelect");
    let mut loaded = load_pef_application(&pef).unwrap();
    let description = (0..40).map(|_| "A").collect::<Vec<_>>().join(";");
    let menu_handle = install_test_popup_menu(
        &mut loaded,
        PPC_DATA_BASE + 0x1000,
        303,
        b"Popup",
        description.as_bytes(),
    );
    loaded.toolbox_startup.host_menu_bar_hidden = true;
    loaded.cpu.gpr[3] = menu_handle;
    loaded.cpu.gpr[4] = 100;
    loaded.cpu.gpr[5] = 120;
    loaded.cpu.gpr[6] = 20;
    loaded.set_input_snapshot(PpcInputSnapshot {
        mouse_button: true,
        mouse_v: 100,
        mouse_h: 124,
        ..PpcInputSnapshot::default()
    });

    let probe = loaded.run_with_hle_imports(64);

    assert!(matches!(probe.result, PpcRunResult::CycleLimit { .. }));
    let tracking = loaded.toolbox_startup.execution.menu().as_ref().unwrap();
    assert_eq!(tracking.popup_top, 4);
    assert_eq!(tracking.popup_height, 576);
    assert_eq!(tracking.content_top, -204);
    assert_eq!(tracking.highlighted_item, 20);
    assert_eq!(
        loaded
            .memory
            .read_u16_be(crate::memory::globals::addr::TOP_MENU_ITEM)
            .map(|value| value as i16),
        Some(-204),
    );
    assert_eq!(
        loaded
            .memory
            .read_u16_be(crate::memory::globals::addr::AT_MENU_BOTTOM)
            .map(|value| value as i16),
        Some(436),
    );
    let indicator_point = (
        i32::from(tracking.popup_left + tracking.popup_width / 2),
        i32::from(tracking.popup_top + 4),
    );
    let front =
        ppc_live_front_buffer_for_gworld(&mut loaded.memory, &loaded.gworlds, PPC_MAIN_GWORLD)
            .unwrap();
    let black =
        ppc_physical_screen_color_pixel(front, PPC_RGB_BLACK, &loaded.screen_clut).unwrap();
    assert_eq!(
        ppc_quickdraw_read_pixel(&mut loaded.memory, front, indicator_point),
        Some(black),
        "the hidden upper content must replace the first visible row with an indicator"
    );
    assert_eq!(
        ppc_menu_tracking_item(
            &mut loaded.memory,
            tracking,
            PpcInputSnapshot {
                mouse_button: true,
                mouse_v: 100,
                mouse_h: tracking.popup_left + 4,
                ..PpcInputSnapshot::default()
            },
        ),
        20,
    );

    let popup_left = tracking.popup_left;
    for (mouse_v, expected_item, expected_top, expected_bottom) in [
        (28, 15, -204, 436),
        (12, 0, -204, 436),
        (12, 0, -188, 452),
        (3, 0, -172, 468),
    ] {
        let action = ppc_dispatch_pop_up_menu_select(
            &loaded.cpu,
            &mut loaded.memory,
            &loaded.gworlds,
            &loaded.screen_clut,
            MenuColorTable::new(&[]),
            &mut loaded.toolbox_startup,
            PpcInputSnapshot {
                mouse_button: true,
                mouse_v,
                mouse_h: popup_left + 4,
                ..PpcInputSnapshot::default()
            },
            &loaded.process_file_system.vfs_resources,
            *loaded.process_file_system.current_resource_file,
        );
        assert!(matches!(action, PpcImportAction::Yield(_)));
        let tracking = loaded.toolbox_startup.execution.menu().as_ref().unwrap();
        assert_eq!(tracking.highlighted_item, expected_item);
        assert_eq!(tracking.content_top, expected_top);
        assert_eq!(
            loaded
                .memory
                .read_u16_be(crate::memory::globals::addr::AT_MENU_BOTTOM)
                .map(|value| value as i16),
            Some(expected_bottom),
        );
    }
}

pub(crate) fn native_menu_hook_fixture() -> (PpcLoadedApp, u32, u32) {
    let pef = synthetic_pef_with_import(b"MenuSelect");
    let mut loaded = load_pef_application(&pef).unwrap();
    let menu = install_test_menu(
        &mut loaded,
        PPC_DATA_BASE + 0x1000,
        128,
        b"File",
        b"Open;Close",
    );
    let menu_record = loaded.memory.read_u32_be(menu).unwrap();
    let descriptor = PPC_DATA_BASE + 0x7100;
    let tvector = PPC_DATA_BASE + 0x7180;
    let marker = PPC_DATA_BASE + 0x7400;
    loaded.memory.add_region(marker, vec![0; 4]);
    let mut set_port = compatibility_binding(
        "InterfaceLib",
        "SetPort",
        PpcImportDispatcherTarget::SetPort,
    );
    set_port.symbol_index = 1;
    set_port.trap_pc = PPC_IMPORT_TRAP_BASE + 4;
    loaded
        .memory
        .add_region(PPC_IMPORT_TRAP_BASE + 4, vec![0; 4]);
    loaded.imports.push(set_port);
    loaded.import_count = 2;
    let callback_entry = PPC_CODE_BASE + 0x4000;
    install_test_powerpc_callback(
        &mut loaded,
        descriptor,
        tvector,
        callback_entry,
        PPC_DATA_BASE + 0x7300,
        test_stack_proc_info(PPC_PROCINFO_SIZE_NONE, &[]),
        &[
            0x7fe8_02a6,
            d_form_u(15, 3, 0, (PPC_DSP_BACK_GWORLD >> 16) as u16),
            d_form_u(24, 3, 3, PPC_DSP_BACK_GWORLD as u16),
            0x4800_0000
                | ((PPC_IMPORT_TRAP_BASE + 4).wrapping_sub(callback_entry + 3 * 4)
                    & 0x03ff_fffc)
                | 1,
            0x7fe8_03a6,
            d_form_u(15, 7, 0, (menu_record >> 16) as u16),
            d_form_u(24, 7, 7, menu_record as u16),
            d_form_u(40, 10, 7, 2),
            d_form_u(14, 10, 10, 1),
            d_form_u(44, 10, 7, 2),
            d_form_u(15, 8, 0, (marker >> 16) as u16),
            d_form_u(24, 8, 8, marker as u16),
            d_form_u(32, 9, 8, 0),
            d_form_u(14, 9, 9, 1),
            d_form_u(36, 9, 8, 0),
            d_form_u(14, 3, 0, 77),
            BLR,
        ],
    );
    loaded.memory.write_u32_be(0x0a30, descriptor).unwrap();
    (loaded, marker, menu_record)
}

#[test]
fn native_menu_tracking_invokes_menu_hook_while_held() {
    let (mut loaded, marker, menu_record) = native_menu_hook_fixture();
    let original_menu_width = loaded.memory.read_u16_be(menu_record + 2).unwrap();
    let original_sp = loaded.cpu.gpr[1];
    let original_return = loaded.cpu.lr;
    let original_port = (*loaded.current_gworld, *loaded.current_gdevice);
    loaded
        .memory
        .write_u16_be(crate::memory::globals::addr::MENU_FLASH, 0)
        .unwrap();
    let initial_point =
        (10u32 << 16) | u32::from((STANDARD_MENU_BAR_FIRST_TITLE_LEFT + 2) as u16);
    loaded.cpu.gpr[3] = initial_point;
    loaded.set_input_snapshot(PpcInputSnapshot {
        mouse_button: true,
        mouse_v: 28,
        mouse_h: 20,
        ..PpcInputSnapshot::default()
    });
    for _ in 0..4 {
        let probe = loaded.run_with_hle_imports(128);
        assert!(matches!(probe.result, PpcRunResult::CycleLimit { .. }));
    }
    assert!(loaded.toolbox_startup.execution.menu().is_some());
    assert_eq!(
        loaded.toolbox_startup.execution.menu().context().native_port,
        Some(original_port),
    );
    assert_eq!(*loaded.current_gworld, PPC_DSP_BACK_GWORLD);
    assert_ne!(
        (*loaded.current_gworld, *loaded.current_gdevice),
        original_port
    );
    assert!(
        loaded.memory.read_u32_be(marker).unwrap() > 0,
        "MenuSelect must invoke MenuHook while held"
    );
    assert!(loaded.memory.read_u16_be(menu_record + 2).unwrap() > original_menu_width);
    loaded.set_input_snapshot(PpcInputSnapshot {
        mouse_button: false,
        mouse_v: 28,
        mouse_h: 20,
        ..PpcInputSnapshot::default()
    });
    for _ in 0..8 {
        let probe = loaded.run_with_hle_imports(128);
        if matches!(probe.result, PpcRunResult::Halted { .. }) {
            break;
        }
    }
    assert_eq!(loaded.cpu.pc, original_return);
    assert_eq!(loaded.cpu.gpr[1], original_sp);
    assert_eq!(loaded.cpu.gpr[3], (128 << 16) | 1);
    assert_eq!(
        (*loaded.current_gworld, *loaded.current_gdevice),
        original_port
    );
    assert!(loaded.guest_calls().is_empty());
    assert!(loaded.toolbox_startup.execution.menu().is_none());
}

#[test]
fn refused_native_menu_hook_leaves_no_receipt_or_port_and_retries() {
    let (mut loaded, marker, _) = native_menu_hook_fixture();
    let descriptor = loaded.memory.read_u32_be(0x0a30).unwrap();
    loaded.memory.write_u32_be(0x0a30, 0).unwrap();
    loaded.cpu.gpr[3] =
        (10u32 << 16) | u32::from((STANDARD_MENU_BAR_FIRST_TITLE_LEFT + 2) as u16);
    loaded.set_input_snapshot(PpcInputSnapshot {
        mouse_button: true,
        mouse_v: 28,
        mouse_h: 20,
        ..PpcInputSnapshot::default()
    });

    let probe = loaded.run_with_hle_imports(128);
    assert!(matches!(probe.result, PpcRunResult::CycleLimit { .. }));
    assert_eq!(loaded.guest_calls().depth(), 0);
    assert_eq!(loaded.toolbox_startup.execution.menu().menu_hook_key(), None);
    assert_eq!(
        loaded.toolbox_startup.execution.menu().context().native_port,
        None
    );
    assert_eq!(loaded.memory.read_u32_be(marker), Some(0));

    loaded.memory.write_u32_be(0x0a30, descriptor).unwrap();
    loaded
        .memory
        .write_u32_be(descriptor + PPC_ROUTINE_DESCRIPTOR_HEADER_SIZE, 1)
        .unwrap();
    let probe = loaded.run_with_hle_imports(128);
    assert!(matches!(probe.result, PpcRunResult::CycleLimit { .. }));
    assert_eq!(loaded.guest_calls().depth(), 0);
    assert_eq!(loaded.toolbox_startup.execution.menu().menu_hook_key(), None);
    assert_eq!(
        loaded.toolbox_startup.execution.menu().context().native_port,
        None
    );
    assert_eq!(loaded.memory.read_u32_be(marker), Some(0));

    loaded
        .memory
        .write_u32_be(descriptor + PPC_ROUTINE_DESCRIPTOR_HEADER_SIZE, 0)
        .unwrap();
    for _ in 0..4 {
        let probe = loaded.run_with_hle_imports(128);
        assert!(matches!(probe.result, PpcRunResult::CycleLimit { .. }));
    }
    assert!(loaded.memory.read_u32_be(marker).unwrap() > 0);
    assert!(loaded
        .toolbox_startup
        .execution.menu()
        .context()
        .native_port
        .is_some());

    loaded.set_input_snapshot(PpcInputSnapshot {
        mouse_button: false,
        mouse_v: 500,
        mouse_h: 500,
        ..PpcInputSnapshot::default()
    });
    for _ in 0..8 {
        if matches!(
            loaded.run_with_hle_imports(128).result,
            PpcRunResult::Halted { .. }
        ) {
            break;
        }
    }
    assert!(loaded.guest_calls().is_empty());
    assert!(loaded.toolbox_startup.execution.menu().is_none());
}

